        { type = "travel", name = "Kill Mountain Lions. Loot them for a [Fresh Carcass]", note = "[Fresh Carcass] disappears after 30 minutes - .collect 5810,1 - .mob Feral Mountain Lion - .mob Mountain Lion - .mob Starving Mountain Lion - .mob Hulking Mountain Lion - .isOnQuest 1136", zone = "Alterac Mountains", x = 41.83, y = 76.57, path = { { zone = "Alterac Mountains", x = 41.83, y = 76.57 }, { zone = "Alterac Mountains", x = 29.12, y = 77.98 }, { zone = "Alterac Mountains", x = 30.69, y = 82.31 }, { zone = "Alterac Mountains", x = 30.48, y = 87.06 }, { zone = "Alterac Mountains", x = 35.35, y = 82.68 }, { zone = "Alterac Mountains", x = 42.83, y = 82.98 } } },
        { type = "complete", name = "Charge the Flame of Uzel inside the Growless Cave", zone = "Alterac Mountains", x = 37.54, y = 66.24, quest = 553, objective = 3 },
        { type = "complete", name = "Frostmaw is level 37. Clear a kiting path outside the cave before summoning him!", note = "Use the [Fresh Carcass] inside Growless Cave to summon Frostmaw. Kill him and loot him for his Mane - This quest is HARD! You could postpone this until after Arathi when you are 1-2 levels higher - Place a [Frost Trap] outside to kite him easily - Use [Kidney Shot] and [Gouge] to run away from him to use [Thrown] and to restore energy. Save [Evasion] and [Sprint] for when he dodges both - Use [Retaliation] if you have it up. Use [Intimidating Shout] to get a full bandage off, but make sure he has no [Bleeds] when you do so - Kite him with rank 1 [Frostbolts] if mana becomes an issue. Remember that he will resist spells at a high frequency - Use your mana mainly on [Shadow Word Pain] and healing as he is likely to resist a lot - Use [Fear] as much as possible but remember that he will resist spells at a high frequency - Stay in [Bear Form] as much as possible, only come out to heal - Don't waste mana on Shock abilities, he will resist too much. Try to kite him with [Earthbind Totem] and save mana for healing - .unitscan Frostmaw - .isOnQuest 1136", zone = "Alterac Mountains", x = 37.56, y = 68.22, quest = 1136, objective = 1 },
        { type = "complete", note = "Use the [Fresh Carcass] inside Growless Cave to summon Frostmaw. Kill him and loot him for his Mane - .unitscan Frostmaw - .isOnQuest 1136", zone = "Alterac Mountains", x = 37.56, y = 68.22, quest = 1136, objective = 1 },
