        { type = "note", name = "As you're questing cast [Drain Soul] on mobs untill you receive an Explorer's Soul. Use it to learn how to summon an [Explorer Imp]", note = "Use Explorer's Soul to learn how to summon an [Explorer Imp] - .train 445459,1 - .train 1120,3 - .use 221978", class = "WARLOCK", optional = true },
        { type = "note", name = "You are in a zone with Fel Portals present. If you find one summon your [Explorer Imp] and talk to it while next to a portal to send it on an expedition. After 10-20 minutes it will return with loot and a chance to award you with [Rune of the Felguard]", note = "You are in a zone with Fel Portals present. If you find one close it using a [Scroll of Spatial Mending]. This will award you with [Spell Notes: Balefire Bolt] - Be on the lookout for the portals untill you get the rune - .collect 221499,1 - .collect 223147,1 - .itemcount 220792,1 - .use 223148 - .use 220792 - .train 429311,1 - .train 431756,1 - .train 1120,3 - .unitscan Fel Sliver - .unitscan Fel Crack - .unitscan Fel Tear - .unitscan Fel Scar - .unitscan Fel Rift", optional = true },
        { type = "note", name = ".itemcount 221499,1 - .itemcount 223147,1 - Use the [Rune of the Felguard] to learn [Summon Felguard] - Use the [Spell Notes: Balefire Bolt to train [Balefire Bolt] - .use 221499 - .use 223147", note = ".itemcount 221499,1 - .itemcount 223147,1 - Use the [Rune of the Felguard] to learn [Summon Felguard] - Use the [Spell Notes: Balefire Bolt to train [Balefire Bolt] - .use 221499 - .use 223147", optional = true },
